"""Assess four saved generic constrained decodes; do not modify standard QA."""
import sys,re
from pathlib import Path
from datetime import datetime,timezone
sys.dont_write_bytecode=True
OUT=Path(__file__).resolve().parent;DELTA=OUT.parent;QA=DELTA.parent
sys.path.insert(0,str(QA))
from prepare import read,sha,pin,dump

def main():
    cfg=read(QA/'config.json');receipt=read(OUT/'run_receipt.json')
    standard=read(OUT/'standard_snapshot/review.json');rows=[];constraints=[]
