    from prepare import ROOT
    inventory[1]={'scope':'embedded_python_site_packages_top_level','path':str(ROOT/'tools/python311/Lib/site-packages'),'exists':(ROOT/'tools/python311/Lib/site-packages').exists(),'matching_entries':[p.name for p in (ROOT/'tools/python311/Lib/site-packages').iterdir() if any(x in p.name.lower() for x in ['vosk','sherpa','funasr','speechbrain','nemo','wav2vec','transformers','torch','whisper','ctranslate','pocketsphinx'])] if (ROOT/'tools/python311/Lib/site-packages').exists() else []}
    for root in [Path(cfg['models']['small']['path']).parent,ROOT/'models',ROOT/'tools/models',Path.home()/'.cache/huggingface/hub']:
        inventory.append({'scope':'model_cache_top_level_only','path':str(root),'exists':root.exists(),'entries':[p.name for p in root.iterdir()] if root.exists() else []})
    dump(OUT/'local_family_inventory.json',{'checked_at':datetime.now(timezone.utc).isoformat(),'scopes':inventory,'ready_independent_non_Whisper_ASR_family_found_in_scanned_scopes':False,'known_ready_models':['Systran multilingual Whisper small CT2','Systran multilingual Whisper medium CT2'],'first_episode_audio_or_transcripts_scanned':False,'global_machine_inventory_claimed':False,'downloads_or_installs':0,'scope_limit':'Only the established shared deps/cache, embeddedPython sitepackages and listed local model roots. Other uninspected environments are unknown.'})
    r={'task':'generic no-ASCII-digit phonetic decode diagnostic','at_utc':datetime.now(timezone.utc).isoformat(),'approved':False,'diagnostic_usable_for_target_numeric_closure':False,'script_sha256':standard['script_sha256'],'final_timing_sha256':standard['final_timing_sha256'],'critical_issues':[],'required_issues':[{'id':'ASR-A2-NUM-001','status':'open_unchanged','severity':'required','evidence':[x for x in rows],'revision':'Retain the standard v3 hold on S019 fee values and S024 required-loan amount. The no-digit decoder produces repetition/deletion rather than the required contrasting Korean numeral sequences.','fix':'Return these exact results and original standard transcripts to main. No further TTS or automatic issue closure is authorized by this report. A different verification method needs its own actual evidence.'}],'prior_TERM_001_disposition':'Unchanged: closed only for literal/canonical mixed-letter ASR identification in standard v3 review. This diagnostic does not reopen or extend it.','standard_review_snapshot':pin(OUT/'standard_snapshot/review.json'),'standard_snapshot_manifest':pin(OUT/'standard_snapshot/manifest.json'),'standard_review_original_unchanged':True,'run_receipt':pin(OUT/'run_receipt.json'),'results':rows,'token_constraint':{'rule':constraints[0]['rule'],'tokenizer_vocabulary_size':50364,'digit_tokens_suppressed':426,'same_digit_token_ids_both_models':True,'digit_token_ids_canonical_json_sha256':constraints[0]['digit_token_ids_canonical_json_sha256'],'requested_suppress_tokens_sha256':constraints[0]['requested_list_sha256'],'effective_suppress_tokens_sha256':constraints[0]['effective_list_sha256'],'effective_token_count':len(constraints[0]['effective_suppress_tokens']),'default_minus1_non_speech_suppression_retained':True,'lexical_list_files':[pin(OUT/n/'token_constraint.json') for n in ['small','medium']],'timestamp_tokens_in_exposed_vocabulary_matching_rule':0,'timestamp_note':'The exposed HuggingFace tokenizer vocabulary has50364 entries and no timestamp entries matching this rule. without_timestamps=True and word_timestamps=False were explicit extra diagnostic settings, not the result of426timestamp token bans. Reported segment timing is not native alignment.','comparison_with_standard':'The digit ban and no-timestamps/word-timestamp settings differ from standard v3. Therefore this experiment cannot isolate all failure causes to one setting.','expected_numeral_allowed_list_or_words_forced':False},'coverage':{'actual_ASR_runs':4,'models':['small','medium'],'scenes':['S019','S024'],'same_unchanged_raw_WAV_SHA':True,'full_target_raw_paragraph_context':True,'clip_selection_or_retries':False,'unique_input_seconds':sum(x['ASR_input_seconds'] for x in rows if x['model']=='small'),'total_model_input_seconds':sum(x['ASR_input_seconds'] for x in rows),'reference_text_used_before_output_for_prompt_or_constraint':False,'initial_prompt':None,'prefix':None,'hotwords':None,'network_calls':0,'paid_calls':0,'TTS_calls':0,'new_model_or_package_downloads':0,'actual_listening':False,'continuous_playback':False,'audio_input_runtime_supported':False,'audio_input_support_basis':'Main explicitly reports runtime audio omitted/unsupported. No audio emission or listening retry was attempted by this task.','source_audio_or_original_standard_QA_modified':False},'independent_family_inventory':pin(OUT/'local_family_inventory.json'),'limitations':['Banning Arabic digits does not force a correct phonetic transcription; it can alter model behavior and cause symbol loops, language switching or omissions.','No target Korean numeral sequence appears in any of the four outputs, so this round cannot distinguish4902from4920or2902from2920/2900.','Deletion in constrained output is a decoder observation, not proof that the source WAV omits speech.','No independent local ASR family is ready in the scanned environment/cache; only the sameWhisper family is confirmed. This is not a claim about every environment on the PC.'],'runner':pin(OUT/'run_phonetic.py'),'review_builder':pin(OUT/'build_review.py')}
    dump(OUT/'review.json',r)
    dump(OUT/'handoff.json',{'status':'four_phonetic_decodes_complete_not_disambiguating_required_hold_retained','approved':False,'script_sha256':r['script_sha256'],'final_timing_sha256':r['final_timing_sha256'],'review':pin(OUT/'review.json'),'run_receipt':pin(OUT/'run_receipt.json'),'standard_v3_review_preserved':pin(OUT/'standard_snapshot/review.json'),'required_issues':[{'id':'ASR-A2-NUM-001','remaining_scene_ids':['S019','S024']}],'four_actual_results':[x['report'] for x in rows],'token_ids_sha256':r['token_constraint']['digit_token_ids_canonical_json_sha256'],'independent_family_inventory':r['independent_family_inventory'],'actual_listening':False,'TTS_calls':0,'further_retries_or_generation_authorized':False})
    print({'actual_runs':4,'digit_tokens':426,'same_token_rule':True,'raw_audio_changed':False,'standard_QA_changed':False,'numeric_disambiguation_usable':False,'approved':False,'required':'ASR-A2-NUM-001 remains open','review':str(OUT/'review.json')})
